def project_odom(point,q,base,spec):
    pose=pose_points(q,spec); yaw=base[2];R=Rotation.from_euler('z',-yaw).as_matrix()
    pp=R@(np.asarray(point)-np.array([base[0],base[1],0]))-pose['cam']
    h,w=spec['cameras']['robot_wrist']['hw'];f=h/(2*np.tan(np.deg2rad(spec['cameras']['robot_wrist']['fovy_deg'])/2))
    d=pp@pose['forward'];u=(w-1)/2+f*(pp@pose['right'])/d;v=(h-1)/2-f*(pp@pose['up'])/d
    return u,v,d

def replay_recorded_actions(client=None, path=LOG):
    """Submit the recorded trajectory to a fresh compatible episode."""
    client = client or Robot()
    last = None
    with Path(path).open() as stream:
        for line in stream:
            entry = json.loads(line)
            last = client.submit('delta', np.asarray(entry['actions'], dtype=float),
                                 cameras=[], video='none')
            if last.meta['done']:
                break
    return last
